def verifier(assign):
    # Validate and recompute the answer theta
    # Return (False, None) on invalid data; use comments to explain.
    def my_gcd(a, b):
        while b:
            a, b = b, a % b
        return a
    def lcm(a, b):
        return a // my_gcd(a, b) * b
    # Check required keys
    required = ['n', 'm', 'a', 'b', 'alpha_deg', 'beta_deg']
    for k in required:
        if k not in assign:
            # Missing key
            return False, None
    n = assign['n']; m = assign['m']; a = assign['a']; b = assign['b']
    alpha_deg = assign['alpha_deg']; beta_deg = assign['beta_deg']
    # Basic type and domain checks
    if not all(isinstance(x, int) for x in [n, m, a, b, alpha_deg, beta_deg]):
        return False, None  # non-integer provided
    if n < 3 or m < 3:
        return False, None  # too small; trivial cyclotomic
    if n == m:
        return False, None  # must be distinct
    if 360 % n != 0 or 360 % m != 0:
        return False, None  # n and m must divide 360
    g = my_gcd(n, m)
    if g == 1:
        return False, None  # need gcd>1 to align grid endpoints
    L = lcm(n, m)
    if 360 % L != 0:
        return False, None  # endpoints grid must divide 360
    step_deg = 360 // L
    # Sector bounds
    if not (0 <= alpha_deg < beta_deg < 360):
        return False, None
    # Enforce alignment to the common grid
    if alpha_deg % step_deg != 0 or beta_deg % step_deg != 0:
        return False, None  # endpoints must be aligned
    # Additionally ensure that alpha*n/360 and beta*n/360 (and for m) are integers
    if (alpha_deg * n) % 360 != 0 or (beta_deg * n) % 360 != 0:
        return False, None
    if (alpha_deg * m) % 360 != 0 or (beta_deg * m) % 360 != 0:
        return False, None
    # Compute index bounds for each order
    low_n = (alpha_deg * n) // 360
    up_n = (beta_deg * n) // 360
    low_m = (alpha_deg * m) // 360
    up_m = (beta_deg * m) // 360
    # Sum primitive indices in ranges
    def sum_totatives(nval, lo, hi):
        ssum = 0
        for k in range(lo + 1, hi + 1):
            if my_gcd(k, nval) == 1:
                ssum += k
        return ssum
    S_n = sum_totatives(n, low_n, up_n)
    S_m = sum_totatives(m, low_m, up_m)
    # Ensure nontriviality: both sums positive for difficulty
    if S_n == 0 or S_m == 0:
        return False, None
    # Compute theta (mod 360)
    theta_total = (a * (360 // n)) * S_n + (b * (360 // m)) * S_m
    theta = theta_total % 360
    # Avoid trivial angles; if occurs, treat as invalid to enforce difficulty
    if theta in (0, 180):
        return False, None
    return True, theta
